from pathlib import Path
import sys,json,hashlib,re
W=Path(__file__).resolve().parent
sys.path.insert(0,'/Volumes/LaCie/open-commentary/_tools')
from build_repo import load_commentary
c=load_commentary(str(W));(W/'sources/review-art-212m-212ij-before-hashes.json').write_text(json.dumps({k:hashlib.sha256(v.encode()).hexdigest() for k,v in c.items()},indent=2))
c['art-212m']='''Artikel 212m is vervallen en biedt thans geen grondslag om een bank failliet te verklaren. De historische tekst van 1 januari 2018 regelde juist de overgang vanuit een noodregeling naar faillissement. Lid 1 bevatte een bijzondere faillissementsgrond, met het horen van ECB of DNB overeenkomstig de toenmalige bevoegdheidsverdeling, negatief eigen vermogen en voorwaarden rond het met de machtiging te bereiken doel. Lid 2 liet noodregeling en machtiging bij faillietverklaring van rechtswege eindigen.

Het oude lid 3 verbond aan die overgang, en aan faillissement binnen vier weken na beëindiging van de noodregeling, afzonderlijke gevolgen: berekening van termijnen voor benadelingshandelingen en bestuurdersaansprakelijkheid, voortzetting van boedelschuldstatus, toerekening van bewindvoerdershandelingen aan de curator, begrenzing van aansprakelijkheid voor onbevoegd aangegane verbintenissen, voortzetting van de vangnetregeling en uitvoering van een overdrachtsplan. Lid 4 verklaarde de eerste titel en artikel 362 overeenkomstig toepasselijk. Dit is historische duiding, geen beschrijving van huidig geldende bevoegdheden.

De bronnoot verwijst naar artikel XIV lid 4 van Stb. 2018/489. Dat lid behoudt de oude Faillissementswet voor verzekeraarsfaillissementen uitgesproken vóór inwerkingtreding van artikel IV; het is geen algemene behoudsregel voor oudere bankfaillissementen. Bijvoorbeeld: een curator vindt een oud model dat de vierwekentermijn noemt. Hij kan die regel niet door alleen naar deze bronnoot te verwijzen op een nieuwe bankprocedure toepassen; daarvoor is een afzonderlijk toepasselijke temporele grondslag nodig.'''
c['art-212ma']='''De huidige nummerplaats is vervallen. In de officiële toestand van 1 januari 2018 had zij een specifieke aanvullende functie: wanneer een bank failliet werd verklaard zonder toepassing van artikel 212m lid 1 of lid 3, werd afdeling 3.5.6 Wft overeenkomstig toepasselijk verklaard. Anders dan artikel 212m zelf bevatte deze bepaling dus geen bijzondere faillissementsgrond of uitgebreide gevolgenregeling bij opvolging van een noodregeling. Zij legde een koppeling met de toenmalige vangnetregeling voor het andere faillissementsscenario.

Die historische verwijzing mag niet als een actuele zelfstandige opdracht tot toepassing van de huidige Wft worden gelezen. De bronnoot over artikel XIV lid 4 van Stb. 2018/489 betreft bovendien behoud van de oude Faillissementswet bij de daar omschreven reeds uitgesproken verzekeraarsfaillissementen. Daaruit volgt geen algemene voortzetting van deze oude bankbepaling. Bijvoorbeeld: een schuldeiser beroept zich op een oude brief waarin artikel 212ma staat. Eerst moeten datum, toepasselijke wetsversie en een eventuele eigen overgangsgrond worden vastgesteld; de huidige vermelding «Vervallen» draagt de gestelde aanspraak niet. De inhoud van de destijds aangehaalde Wft-afdeling is hier niet als huidig recht gereconstrueerd.'''
c['art-212o']=c['art-212o'].replace('gezien de verwijzingsregels vanaf artikel 212t','gezien het onderscheid tussen hoofdregel en bijzondere uitzonderingen, dat bij inkomende liquidaties zichtbaar wordt in artikel 212t en volgende').replace('Voor een ouder faillissement verdient de bij de officiële tekst vermelde overgangsrechtelijke verwijzing afzonderlijke controle.','De bronnoot verwijst naar artikel XIV lid 4 van Stb. 2018/489: die behoudsregel betreft de daar omschreven oudere verzekeraarsfaillissementen en is geen algemene uitzondering voor oudere bankprocedures.')
c['art-212p']=c['art-212p'].replace('De verwijzingen mogen niet worden gereduceerd tot één ongedifferentieerde uiterste datum.','De verwijzingen moeten worden gelezen met de actuele tekst: artikel 109 lid 1 regelt de kennisgeving van de beschikking van artikel 108; artikel 127 lid 1 bepaalt als uitgangspunt veertien dagen vóór de eerste verificatievergadering en lid 2 laat aanpassing door de rechter-commissaris toe. Lid 3 van artikel 127 verbindt aan te late indiening dat de vordering niet voor verificatie in behandeling wordt genomen. De enigszins onhandige verwijzing in artikel 212p naar een termijn in artikel 109 lid 1 mag niet stilzwijgend als een daar uitgeschreven afzonderlijke termijn worden weergegeven.')
c['art-212rc']=c['art-212rc'].replace('bij een al eerder geopend faillissement mag de huidige renteregel daarom niet zonder temporele controle worden toegepast.','dat artikel behoudt de oude Faillissementswet voor faillissementen van banken of beleggingsondernemingen die vóór de inwerkingtreding van artikel II zijn uitgesproken. De datum van indiening van de rentevordering alleen bepaalt dus niet de toepasselijke versie.')
c['art-212rd']=c['art-212rd'].replace('voor oudere procedures moet het in de bron vermelde overgangsrecht worden nagegaan.','artikel III van Stb. 2022/105 behoudt de oude Faillissementswet bij een bank- of beleggingsondernemingsfaillissement uitgesproken vóór inwerkingtreding van artikel II. Een later betalingsvoorstel maakt die oudere procedure niet vanzelf onderworpen aan deze nieuwe bevoegdheid.')
c['art-212re']=c['art-212re'].replace('Bij oudere uitgiften of procedures verdient ook de officiële verwijzing naar artikel III van Stb. 2022/22 aandacht; de actuele bepaling geldt sinds 8 juli 2022.','Artikel III lid 1 van Stb. 2022/22 sluit artikel 212re uit voor de daar omschreven geregistreerde gedekte obligaties die tot en met 7 juli 2022 zijn uitgegeven. Lid 3 breidt die overgangsbehandeling tot en met 7 juli 2024 uit tot de daar nader gekwalificeerde obligaties. De uitgiftedatum en overgangscategorie zijn daarom beslissend; de ingangsdatum van de actuele bepaling, 8 juli 2022, rechtvaardigt niet de conclusie dat elke later behandelde obligatie eronder valt.')
changed={'art-212'+x for x in ['m','ma','o','p','rc','rd','re']}
for p in (W/'commentary').glob('*.md'):
 s=p.read_text();parts=re.split(r'(?m)^=== ',s);out=[parts[0]]
 for part in parts[1:]:
  k,sep,body=part.partition('\n');out.append('=== '+k+'\n'+(c[k].rstrip()+'\n\n' if k in changed else body))
 t=''.join(out)
 if t!=s:p.write_text(t)
print('Corrected seven assigned commentaries; all others preserved.')
